pub fn confLoad(allo: std.mem.Allocator, iozz: std.Io, path: []const u8) !Conf { const byte = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(CF.maxz)) catch |err3| { if (err3 == error.FileNotFound) return .{}; return err3; }; return confPars(allo, byte); }
pub fn confKeyz(allo: std.mem.Allocator, byte: []const u8) ?[]const u8 { const valu = std.json.parseFromSliceLeaky(std.json.Value, allo, byte, .{}) catch return null; if (valu != .object) return null; var iter = valu.object.iterator(); while (iter.next()) |item| { var known = false; inline for (@typeInfo(Conf).@"struct".field_names) |fnam| { if (std.mem.eql(u8, fnam, item.key_ptr.*)) known = true; } if (!known) return item.key_ptr.*; } return null; }
pub fn confPars(allo: std.mem.Allocator, byte: []const u8) !Conf { if (confKeyz(allo, byte)) |keyz| { std.debug.print("config error: unknown key \"{s}\" (fix the name or remove it)\n", .{keyz}); return error.BadConfig; } const conf = std.json.parseFromSliceLeaky(Conf, allo, byte, .{ .ignore_unknown_fields = false, .allocate = .alloc_always }) catch return error.BadConfig; try confChek(conf); return conf; }
pub fn confChek(conf: Conf) !void { if (conf.runz_time_seco < 60 or conf.runz_time_seco > 86400) return error.BadConfig; if ((conf.brow_wind_widt == 0) != (conf.brow_wind_high == 0) or conf.brow_wind_widt > 10000 or conf.brow_wind_high > 10000 or !std.math.isFinite(conf.brow_wind_scal) or (conf.brow_wind_scal != 0 and (conf.brow_wind_scal < 0.25 or conf.brow_wind_scal > 4)) or conf.brow_wind_left < -100 or conf.brow_wind_left > 10000) return error.BadConfig; if (!std.math.isFinite(conf.capz_usdz_mont) or conf.capz_usdz_mont < 0) return error.BadConfig; if (conf.capz_disk_gbyt == 0 or conf.fetc_time_seco == 0 or conf.fetc_body_maxz == 0 or conf.retr_cont_maxz == 0) return error.BadConfig; if (!inzzLisz(CF.mods, conf.clou_poli_mode)) return error.BadConfig; if (conf.vend_orde.len == 0 or conf.revi_floo_seco == 0 or conf.revi_floo_seco > conf.revi_capz_seco or conf.revi_star_seco < conf.revi_floo_seco or conf.revi_star_seco > conf.revi_capz_seco) return error.BadConfig; for (conf.vend_orde) |vend| if (!inzzLisz(CF.vend, vend)) return error.BadConfig; for (conf.clou_stor_orde) |item| if (!inzzLisz(CF.stor, item)) return error.BadConfig; for (conf.clou_sqlz_orde) |item| if (!inzzLisz(CF.sqlz, item)) return error.BadConfig; if (conf.clou_sync_batz == 0 or conf.clou_mirr_batz == 0 or conf.clou_mirr_opsa_mont == 0 or conf.clou_mirr_spoo_maxz == 0) return error.BadConfig; try purgChek(conf); try carzChek(conf); if (conf.geoz_code_dflt.len > 0 and !geozOkay(conf.geoz_code_dflt)) return error.BadConfig; var gite = conf.geoz_host_over.map.iterator(); while (gite.next()) |entr| if (!geozOkay(entr.value_ptr.*)) return error.BadConfig; }
fn carzChek(conf: Conf) !void { if (conf.carz_text_days == 0 or conf.carz_hist_days == 0 or conf.carz_gone_days == 0 or conf.carz_pers_days == 0 or conf.carz_stal_days == 0 or conf.carz_dead_days == 0 or conf.carz_pull_maxz == 0) return error.BadConfig; if (conf.carz_stal_days >= conf.carz_dead_days or conf.cont_week_keep == 0 or conf.cont_week_keep > 52) return error.BadConfig; if (conf.soci_time_seco == 0 or conf.soci_line_maxz < 256 or conf.soci_file_maxz < conf.soci_line_maxz) return error.BadConfig; for (conf.soci_engi_list) |item| { if (std.mem.indexOfScalar(u8, item, '|') == null) return error.BadConfig; } if (conf.carz_text_days > conf.carz_gone_days or conf.carz_hist_days > conf.carz_gone_days) return error.BadConfig; }
fn purgChek(conf: Conf) !void { if (conf.purg_high_pctz < 2 or conf.purg_high_pctz > 100 or conf.purg_lowz_pctz < 1 or conf.purg_lowz_pctz >= conf.purg_high_pctz) return error.BadConfig; if (conf.purg_maxx_pctz == 0 or conf.purg_maxx_pctz > 100 or conf.purg_dead_pctz == 0 or conf.purg_dead_pctz > 100) return error.BadConfig; if (conf.purg_loca_days == 0 or conf.purg_dbzz_body_days == 0 or conf.purg_dbzz_gone_days == 0 or conf.purg_logz_days == 0 or conf.purg_outb_days == 0 or conf.purg_dead_days == 0 or conf.purg_veri_days == 0 or conf.purg_live_days == 0) return error.BadConfig; if (conf.purg_veri_cont > 100 or conf.clou_fail_runs == 0) return error.BadConfig; if (conf.clou_body_maxz < 1024 or conf.clou_body_maxz > 60000) return error.BadConfig; if (conf.clou_sqlz_capz_mbyt.turs == 0 or conf.clou_sqlz_capz_mbyt.neon == 0 or conf.clou_sqlz_capz_mbyt.tidb == 0) return error.BadConfig; for ([_]f64{ conf.clou_capz_gbyt.b2zz, conf.clou_capz_gbyt.r2zz, conf.clou_capz_gbyt.tigr }) |gbyt| { if (!std.math.isFinite(gbyt) or gbyt <= 0) return error.BadConfig; } }
fn geozOkay(code: []const u8) bool { return code.len == 2 and std.ascii.isAlphabetic(code[0]) and std.ascii.isAlphabetic(code[1]); }
fn inzzLisz(list: []const []const u8, item: []const u8) bool { for (list) |each| if (std.mem.eql(u8, each, item)) return true; return false; }
pub fn dataDirz(conf: Conf) []const u8 { return if (@import("builtin").os.tag == .windows) conf.data_dirz_wind else conf.data_dirz_unix; }
pub fn capzMicr(conf: Conf) u64 { return @intFromFloat(@round(conf.capz_usdz_mont * CF.micr)); }
